import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:yoclip_core/yoclip_core.dart';
import 'package:yoclip_encoder/yoclip_encoder.dart' as encoder_lib;

void main() {
  final outputPath = Platform.environment['YOCLIP_OUTPUT'];

  final externalImageBytes = <String, Uint8List>{
    for (final e in {"logo":"","logo_on_light":"","golden_hollywood":"","golden_banner":"","golden_rally":"","golden_code":"","golden_helmet":"","golden_cta":""}.entries)
      e.key: base64Decode(e.value as String),
  };

  testWidgets(
    'yoclip render mp4',
    (tester) async {
      if (outputPath == null) return;
      const projectPath = '/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea/.';

      final storage = LocalFileSystemStorage(projectPath);
      final project = await YoclipProject.load(storage, projectPath);

      final runtime = createYoclipJsRuntime();
      await runtime.init();
      addTearDown(runtime.dispose);

      final variant = project.config.variants.firstWhere(
        (v) => v.id == "dark_en",
        orElse: () => throw StateError(
          'Unknown variant "dark_en". Available: ${project.config.variants.map((v) => v.id).join(', ')}',
        ),
      );
      final scenes = await loadYoclipProjectScenes(runtime, project, storage, variant: variant);

      final audioTracks = await YoclipV2AudioResolver(storage).resolveAll(
        project,
        scenes,
        externalAudioFiles: {},
      );
      final audioSpecs = await YoclipV2AudioResolver(storage).toEncoderSpecs(audioTracks);
      final encoderAudioSpecs = audioSpecs
          .map(
            (s) => encoder_lib.YoclipAudioTrackSpec(
              source: s.source,
              volume: s.volume,
              startFrame: s.startFrame,
              envelope: s.envelope,
            ),
          )
          .toList();

      final renderProject = resolveYoclipAutoDuration(project, scenes);
      final adjustedProject = YoclipProject(
        rootPath: renderProject.rootPath,
        config: YoclipProjectConfig(
          duration: renderProject.config.autoDuration
              ? renderProject.config.duration
              : 2580,
          fps: 30,
          width: 1920,
          height: 1080,
          background: renderProject.config.background,
          theme: renderProject.config.theme,
          overlay: renderProject.config.overlay,
        ),
        externalAssets: renderProject.externalAssets,
        scenePaths: renderProject.scenePaths,
        pluginPaths: renderProject.pluginPaths,
        fonts: renderProject.fonts,
      );

      final renderer = YoclipV2Renderer(
        project: adjustedProject,
        scenes: scenes,
        storage: storage,
        externalFiles: {"logo":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea/.yoclip_cache/external/logo/yoclip_logo.svg","logo_on_light":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea/.yoclip_cache/external/logo_on_light/yoclip_logo_on_light.svg","golden_hollywood":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea/.yoclip_cache/external/golden_hollywood/hollywood.png","golden_banner":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea/.yoclip_cache/external/golden_banner/banner.png","golden_rally":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea/.yoclip_cache/external/golden_rally/rally.png","golden_code":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea/.yoclip_cache/external/golden_code/code.png","golden_helmet":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea/.yoclip_cache/external/golden_helmet/helmet.png","golden_cta":"/Users/Uladzimir_Klyshevich/git/yoclip/samples/samples/yoclip_big_idea/.yoclip_cache/external/golden_cta/cta.png"},
        externalFrameDirs: {},
        externalImageBytes: externalImageBytes,
      );

      final encoder = encoder_lib.YoclipEncoderTool(
        outputPath: outputPath,
        width: 1920,
        height: 1080,
        fps: 30,
        audioTracks: encoderAudioSpecs,
        videoBitrate: null,
      );

      await tester.runAsync(encoder.start);
      await renderer.renderToRgba(tester, (frame, rgba) async {
        await tester.runAsync(() => encoder.appendFrame(Uint8List.fromList(rgba)));
      });
      await tester.runAsync(encoder.finish);

      final outputFile = File(outputPath);
      expect(outputFile.existsSync(), isTrue);
      expect(outputFile.lengthSync(), greaterThan(1000));
    },
    skip: outputPath == null,
  );
}
